from collections import deque
from typing import List, Tuple

def solve(grid: List[str], start: Tuple[int, int], goal: Tuple[int, int]) -> List[Tuple[int, int]]:
    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0])

    def inside(r: int, c: int) -> bool:
        return 0 <= r < rows and 0 <= c < cols

    # Validate start and goal positions
    if not (inside(*start) and inside(*goal)):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    # Breadth‑first search
    q = deque([start])
    visited = {start}
    parent = {start: None}
    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    while q:
        r, c = q.popleft()
        if (r, c) == goal:
            # Reconstruct path from goal to start
            path = []
            cur = goal
            while cur is not None:
                path.append(cur)
                cur = parent[cur]
            path.reverse()
            return path
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if inside(nr, nc) and grid[nr][nc] == '.' and (nr, nc) not in visited:
                visited.add((nr, nc))
                parent[(nr, nc)] = (r, c)
                q.append((nr, nc))

    # No path found
    return []

