            nr, nc = r + dr, c + dc
            if not is_free(nr, nc) or (nr, nc) in visited:
                continue
            new_path = path + [(nr, nc)]
            if (nr, nc) == goal:
                return new_path
            visited.add((nr, nc))
            q.append((nr, nc, new_path))
    return []

