def solve(grid: List[str], start: Tuple[int, int], goal: Tuple[int, int]) -> List[Tuple[int, int]]:
    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0])
    # Validate coordinates
    def in_bounds(r, c):
        return 0 <= r < rows and 0 <= c < cols
    sr, sc = start
    gr, gc = goal
    if not (in_bounds(sr, sc) and in_bounds(gr, gc)):
        return []
    if grid[sr][sc] == '#' or grid[gr][gc] == '#':
        return []
    if start == goal:
        return [start]

    # BFS to find any path
    q = deque()
    q.append(start)
    prev = {start: None}
    dirs = [(1,0), (-1,0), (0,1), (0,-1)]

    while q:
        r, c = q.popleft()
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            nxt = (nr, nc)
            if not in_bounds(nr, nc):
                continue
            if grid[nr][nc] == '#':
                continue
            if nxt in prev:
                continue
            prev[nxt] = (r, c)
            if nxt == goal:
                # reconstruct path
                path = []
                cur = goal
                while cur is not None:
                    path.append(cur)
                    cur = prev[cur]
                path.reverse()
                return path
            q.append(nxt)

    return []  # no path found

